import { readdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");

/** Build output and coverage, regenerated by `bun run build` / `bun run test:coverage`. */
for (const dir of ["dist", "coverage"]) {
  rmSync(join(repoRoot, dir), { recursive: true, force: true });
}
/** npm-pack tarballs left in the repo root by local runs of the e2e suite. */
for (const name of readdirSync(repoRoot)) {
  if (/^deepseek-web-retrieval-.*\.tgz$/.test(name)) rmSync(join(repoRoot, name));
}
console.log("cleaned dist/, coverage/, and packed tarballs");
